import pdfplumber
import pandas as pd
import json

def clean_value(val):
    if val is None:
        return None
    if isinstance(val, str):
        val = val.strip()
        # Handle numeric strings with commas
        if "," in val and any(char.isdigit() for char in val):
            try:
                return int(val.replace(",", ""))
            except ValueError:
                pass
        # Try to convert to int or float if it looks like a number
        try:
            if "." in val:
                return float(val)
            return int(val)
        except ValueError:
            return val
    return val

# 1. Extract from PDF
pdf_data = []
with pdfplumber.open("employees_backup.pdf") as pdf:
    for page in pdf.pages:
        table = page.extract_table()
        if table:
            headers = table[0]
            for row in table[1:]:
                # Create a dict for each row
                record = {headers[i]: clean_value(row[i]) for i in range(len(headers))}
                if record.get("ID"):
                    pdf_data.append(record)

# 2. Extract from Excel
df_excel = pd.read_excel("employees_current.xlsx")
# Convert excel data to list of dicts for easier comparison, and clean values
excel_data = []
for _, row in df_excel.iterrows():
    record = {col: clean_value(row[col]) for col in df_excel.columns}
    excel_data.append(record)

# 3. Compare
pdf_dict = {r["ID"]: r for r in pdf_data}
excel_dict = {r["ID"]: r for r in excel_data}

deleted_employees = []
for emp_id in pdf_dict:
    if emp_id not in excel_dict:
        deleted_employees.append(emp_id)

modified_employees = []
fields_to_compare = ['First', 'Last', 'Dept', 'Position', 'Salary', 'Years', 'Location', 'Score']

for emp_id, excel_record in excel_dict.items():
    if emp_id in pdf_dict:
        pdf_record = pdf_dict[emp_id]
        for field in fields_to_compare:
            old_val = pdf_record.get(field)
            new_val = excel_record.get(field)

            # Special handling for floats to avoid precision issues
            if isinstance(old_val, (int, float)) and isinstance(new_val, (int, float)):
                if abs(old_val - new_val) > 1e-9:
                    modified_employees.append({
                        "id": emp_id,
                        "field": field,
                        "old_value": old_val,
                        "new_value": new_val
                    })
            elif old_val != new_val:
                modified_employees.append({
                    "id": emp_id,
                    "field": field,
                    "old_value": old_val,
                    "new_value": new_val
                })

# 4. Sort results
deleted_employees.sort()
modified_employees.sort(key=lambda x: (x["id"], x["field"]))

# 5. Output
result = {
    "deleted_employees": deleted_employees,
    "modified_employees": modified_employees
}

with open("diff_report.json", "w") as f:
    json.dump(result, f, indent=2)

print(f"Successfully wrote {len(deleted_employees)} deleted and {len(modified_employees)} modified employees to diff_report.json")

